+    // Initialize C to zero (O(N^2))
+    for (int j = 0; j < n * n; ++j) C[j] = 0.0f;
+
+    // i-k-j loop structure for cache efficiency
+    for (int i = 0; i < n; ++i) {
+        int k = 0;
+        // Unrolled K loop (factor 2)
+        for (; k <= n - 2; k += 2) {
+            float aik0 = A[i * n + k];
+            float aik1 = A[i * n + k + 1];
+
+            // Vectorized/Scalar J loop for k and k+1
+            int j = 0;
+            for (; j <= n - 4; j += 4) {
+                float32x4_t v_c = vld1q_f32(&C[i * n + j]);
+                float32x4_t v_b0 = vld1q_f32(&B[k * n + j]);
+                float32x4_t v_b1 = vld1q_f32(&B[(k + 1) * n + j]);
+                float32x4_t v_t0 = vmulq_f32(vdupq_n_f32(aik0), v_b0);
+                float32x4_t v_t1 = vmulq_f32(vdupq_n_f32(aik1), v_b1);
+                v_c = vaddq_f32(v_c, v_t0);
+                v_c = vaddq_f32(v_c, v_t1);
+                vst1q_f32(&C[i * n + j], v_c);
+            }
+            
+            // Scalar remainder loop for k and k+1
+            for (; j < n; ++j) {
+                C[i * n + j] += aik0 * B[k * n + j];
+                C[i * n + j] += aik1 * B[(k + 1) * n + j];
+            }
         }
+
+        // Handle odd K remainder
+        if (n % 2 != 0) {
+            int k_rem = n - 1;
+            float aik_rem = A[i * n + k_rem];
+            
+            int j = 0;
+            // Vectorized J loop
+            for (; j <= n - 4; j += 4) {
+                float32x4_t v_c = vld1q_f32(&C[i * n + j]);
+                float32x4_t v_b = vld1q_f32(&B[k_rem * n + j]);
+                float32x4_t v_a = vdupq_n_f32(aik_rem);
+                v_c = vaddq_f32(v_c, vmulq_f32(v_a, v_b));
+                vst1q_f32(&C[i * n + j], v_c);
+            }
+            
+            // Scalar J remainder loop
+            for (; j < n; ++j) {
+                C[i * n + j] += aik_rem * B[k_rem * n + j];
+            }
+        }
+    }
 }
